import { constants } from "node:os";
import { errno, load } from "koffi";
import { inspectProcess } from "../inspectProcess.ts";

const library = load(null);
const sysctl = library.func("int sysctl(int *name, unsigned int namelen, void *oldp, size_t *oldlenp, void *newp, size_t newlen)");

// KERN_PROCARGS2 returns argc, the executable path, argv, and then the environment.
// Match environment entries only; a command argument can contain the same text.
export function environmentFromArgs(data: Buffer): string[] {
	const argc = data.readInt32LE(0);
	let offset = data.indexOf(0, 4) + 1;
	while (offset < data.length && data[offset] === 0) offset++;
	for (let index = 0; index < argc; index++) {
		const end = data.indexOf(0, offset);
		if (end < 0) throw new Error("The process argument list is incomplete");
		offset = end + 1;
	}
	return data.subarray(offset).toString().split("\0").filter(Boolean);
}

export function processEnvironmentReader() {
	const maximum = Buffer.alloc(4);
	const size = Buffer.alloc(8);
	size.writeBigUInt64LE(4n);
	if (sysctl(new Int32Array([1, 8]), 2, maximum, size, null, 0) !== 0)
		throw new Error(`Cannot read the process argument limit: errno ${errno()}`);
	const data = Buffer.alloc(maximum.readInt32LE(0));
	return (pid: number): string[] => {
		size.writeBigUInt64LE(BigInt(data.length));
		if (sysctl(new Int32Array([1, 49, pid]), 3, data, size, null, 0) !== 0) {
			const failure = errno();
			if (failure === constants.errno.ESRCH || inspectProcess(pid).kind === "missing") return [];
			throw new Error(`Cannot inspect process ${pid}: errno ${failure}`);
		}
		return environmentFromArgs(data.subarray(0, Number(size.readBigUInt64LE())));
	};
}
EOF
